// The synthetic data generator (#131, `analytics/generator/`, Python) against the app's own
// contracts: its events must pass the #129 schemas, and its port of the cart pricing must price
// carts exactly like `priceCart`. The fixtures are generated by `analytics/generator/fixtures.py`;
// its pytest suite fails while they are stale.
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { parseEventProperties } from "~/lib/analytics.schema";
import { EVENT_TYPES, type EventType } from "~/lib/enums";
import { type PricingDiscount, type PricingLine, priceCart } from "./services/pricing";

const FIXTURES = "analytics/generator/fixtures";

interface SampleEvent {
  event_type: EventType;
  event_properties: unknown;
}

interface PricingCase {
  now: string;
  lines: PricingLine[];
  candidates: (Omit<PricingDiscount, "startsAt" | "endsAt"> & {
    startsAt: string | null;
    endsAt: string | null;
  })[];
  expected: {
    subtotal: number;
    discount: number;
    total: number;
    freeShipping: boolean;
    discountId: number | null;
    allocation: number[];
  };
}

function fixture<T>(name: string): T {
  return JSON.parse(readFileSync(`${FIXTURES}/${name}`, "utf8")) as T;
}

describe("synthetic events (#131)", () => {
  const events = fixture<SampleEvent[]>("sample-events.json");

  it("cover every event type the shop records", () => {
    const types = new Set(events.map((e) => e.event_type));
    for (const type of EVENT_TYPES) {
      if (type !== "review_submit") expect(types, type).toContain(type);
    }
  });

  it("match the event properties contract", () => {
    for (const event of events) {
      expect(
        parseEventProperties(event.event_type, event.event_properties),
        JSON.stringify(event),
      ).not.toBeNull();
    }
  });
});

describe("synthetic pricing (#131)", () => {
  const cases = fixture<PricingCase[]>("pricing-cases.json");

  it("prices every generated cart like the app", () => {
    expect(cases.length).toBeGreaterThan(50);
    for (const c of cases) {
      const candidates = c.candidates.map((d) => ({
        ...d,
        startsAt: d.startsAt === null ? null : new Date(d.startsAt),
        endsAt: d.endsAt === null ? null : new Date(d.endsAt),
      }));
      const priced = priceCart(c.lines, candidates, new Date(c.now));
      expect(
        {
          subtotal: priced.subtotal,
          discount: priced.discount,
          total: priced.total,
          freeShipping: priced.freeShipping,
          discountId: priced.applied?.discountId ?? null,
          allocation: priced.allocation,
        },
        JSON.stringify(c.lines),
      ).toEqual(c.expected);
    }
  });
});
